source.registration:
c("H01-002", "BuildMarker single source", "Exactly one module exports BUILD_MARKER; marker literals only in AUTHORITY/HISTORY/FIXTURE roles.", async (ctx) => {
    const r = (await ctx.inspection()).marker;
    return verdict(r.ok, ev(CLASS.STATIC, "build-time syntax inspection manifest", { authorityExports: r.authorityExports, literalFiles: r.literalFiles, unexpected: r.unexpected },
      { authorityExports: ["/src/foundation/buildMarker.js"], unexpected: [] }, "Static source scan"));
  })

c("H01-003", "Displayed marker matches application marker", "Every rendered [data-build-marker] element shows the canonical marker.", async () => {
    const els = Array.from(document.querySelectorAll("[data-build-marker]"));
    if (!els.length) return blockedResult(ev(CLASS.LIVE_RUNTIME, "DOM", 0, "≥1 marker element", "No marker element rendered"));
    const values = [...new Set(els.map((e) => e.textContent.trim()))];
    return verdict(values.length === 1 && values[0] === BUILD_MARKER, ev(CLASS.LIVE_RUNTIME, "DOM [data-build-marker]", values, [BUILD_MARKER], `${els.length} element(s) inspected`));
  }, { runnerType: RUNNER.DOM, classification: CLASS.LIVE_RUNTIME })

c("H01-004", "Current environment resolved", "Runtime environment resolves to LOCAL, PREVIEW or PUBLISHED.", async () => {
    const env = resolveEnvironment();
    return verdict(["LOCAL", "PREVIEW", "PUBLISHED"].includes(env.id), ev(CLASS.LIVE_RUNTIME, "window.location", env.id, "LOCAL|PREVIEW|PUBLISHED", "Resolved from real runtime location"));
  }, { runnerType: RUNNER.RUNTIME, classification: CLASS.LIVE_RUNTIME })

c("H01-006", "Build Ledger consistent with canonical marker", "Active source holds at most five unique +1 sequential packages including current; generated history matches; historic evidence aliases are explicit and missing evidence is NOT_RECORDED.", async (ctx) => {
    const history = (await ctx.inspection()).activeBuildHistory;
    const r = validateLedger(BUILD_LEDGER, BUILD_MARKER);
    const evidenceLabelsValid=BUILD_LEDGER.every(entry=>[["source_changed","source_of_truth_updated"],["tests_changed","tests_updated"],["health_changed","health_cases_updated"],["docs_aligned","docs_aligned"]].every(([current,legacy])=>["true","false","NOT_RECORDED"].includes(buildEvidence(entry,current,legacy))));
    return verdict(r.ok && history.generatedMatches && evidenceLabelsValid, ev(CLASS.STATIC, "src/foundation/buildLedgerData.js + generated history", { entries: BUILD_LEDGER.length, evidenceLabelsValid, generatedMatches: history.generatedMatches, errors: r.errors }, { errors: [] }, "Ledger validation"));
  })

c("H02-001", "All canonical MD files exist", "The 13 canonical docs exist under docs/shinka/.", async (ctx) => {
    const r = (await ctx.inspection()).docs;
    return verdict(r.missing.length === 0, ev(CLASS.STATIC, "docs/shinka/*.md", { present: r.present, missing: r.missing }, { present: 13, missing: [] }, "Doc file inspection"));
  })

c("H02-002", "Canonical MD headers and BuildMarker aligned", "Every doc has the standard header; Current BuildMarker equals the canonical marker.", async (ctx) => {
    const r = (await ctx.inspection()).docs;
    return verdict(r.headerGaps.length === 0 && r.misaligned.length === 0, ev(CLASS.STATIC, "docs/shinka/*.md headers", { headerGaps: r.headerGaps, misaligned: r.misaligned }, { headerGaps: [], misaligned: [] }, "Header inspection"));
  })

c("H02-003", "Source inventory registers 10 LOGICAL sources", "Inventory contains 10 unique logical sources with version, date, domain and authority (physical parts are not logical sources).", async () => {
    const ids = new Set(SOURCE_INVENTORY.map((s) => s.id));
    const complete = SOURCE_INVENTORY.every((s) => s.file && s.version && s.date && s.domain && s.authority && s.status);
    return verdict(SOURCE_INVENTORY.length === LOGICAL_SOURCE_COUNT && ids.size === LOGICAL_SOURCE_COUNT && complete, ev(CLASS.STATIC, "src/foundation/sourceInventory.js", { logical: SOURCE_INVENTORY.length, unique: ids.size, complete, physical: physicalAttachmentCount() }, { logical: 10, unique: 10, complete: true }, "Logical inventory inspection"));
  })

c("H02-004", "All logical sources and physical parts read", "Each logical source is READ and, where split, every physical part is READ.", async () => {
    const notRead = SOURCE_INVENTORY.filter((s) => s.status !== "READ").map((s) => s.file);
    const partsNotRead = SOURCE_INVENTORY.flatMap((s) => (s.parts || []).filter((p) => p.status !== "READ").map((p) => p.file));
    const ok = !notRead.length && !partsNotRead.length;
    const e = ev(ok ? CLASS.STATIC : CLASS.BLOCKED_EXTERNAL, "src/foundation/sourceInventory.js", { logicalRead: LOGICAL_SOURCE_COUNT - notRead.length, notRead, partsNotRead }, { logicalRead: 10, notRead: [], partsNotRead: [] },
      ok ? "SOURCE_RECEIVED_AND_RECORDED; original artifacts are external, not hash-verified in Git" : "Required source/part not supplied");
    return verdict(ok, e, STATUS.BLOCKED);
  })

c("H02-005", "Source authority table exists", "Every required domain has a registered primary source; DB v1.2 supersedes DB v1.1.", async () => {
    const ids = SOURCE_INVENTORY.map((s) => s.id);
    const uncovered = REQUIRED_AUTHORITY_DOMAINS.filter((d) => !AUTHORITY_TABLE.find((a) => a.domain === d && ids.includes(a.primary)));
    const dbRule = AUTHORITY_TABLE.find((a) => a.domain === "DATA_MODEL")?.primary === "SRC-05" && /SUPERSEDED/.test(SOURCE_INVENTORY.find((s) => s.id === "SRC-06").authority);
    return verdict(uncovered.length === 0 && dbRule, ev(CLASS.STATIC, "AUTHORITY_TABLE", { uncovered, dbV12Wins: dbRule }, { uncovered: [], dbV12Wins: true }, "Authority inspection"));
  })

c("H02-006", "No unresolved conflict silently marked resolved", "Resolved decisions cite a rule; OPEN decisions carry impact and are listed in SOURCE_OF_TRUTH.md.", async (ctx) => {
    const doc = (await ctx.inspection()).docs;
    const badResolved = OPEN_DECISIONS.filter((d) => d.status.startsWith("RESOLVED") && !d.resolution_rule).map((d) => d.id);
    const badOpen = OPEN_DECISIONS.filter((d) => d.status === "OPEN" && (!d.impact || !d.recommendation)).map((d) => d.id);
    const undocumented = doc.undocumentedDecisions;
    return verdict(!badResolved.length && !badOpen.length && !undocumented.length, ev(CLASS.STATIC, "openDecisions.js + SHINKA_SOURCE_OF_TRUTH.md", { badResolved, badOpen, undocumented }, { badResolved: [], badOpen: [], undocumented: [] }, `${OPEN_DECISIONS.length} decisions inspected`));
  })

c("H02-007", "Split UI/UX source reconstructed completely", "UI/UX v1.1 = 1 logical source in 4 physical parts: all registered, read, ordered 1→2→3→4, no gap/duplicate, continuity recorded, sole UI/UX authority; machine-readable companion registered as supporting artifact (not a logical source).", async (ctx) => {
    const r = checkSplitSource(SOURCE_INVENTORY, AUTHORITY_TABLE, UIUX_CONTINUITY);
    const doc = (await ctx.inspection()).docs;
    const documented = doc.splitDocumented;
    return verdict(r.ok && documented, ev(CLASS.STATIC, "sourceInventory.js + SHINKA_SOURCE_OF_TRUTH.md", { ...r, documented, boundaries: UIUX_CONTINUITY.boundaries }, { ok: true, documented: true, partCount: 4, companionPresent: true, companionAsLogicalSource: 0, logicalCount: 10 }, "Logical/physical source integrity by role"));
  })

c("H02-008", "UI/UX tables machine-readable (OD-010)", "All 11 UI/UX v1.1 tables represented via the SRC-03 companion: design table = implemented tokens, icon table = nav contract, 5 copy/state groups non-empty, QA checklist complete, logical count unchanged; OD-010 closed.", async (ctx) => {
    const r = checkUiuxTables(uiuxTablesInput());
    const od = OPEN_DECISIONS.find((d) => d.id === "OD-010");
    const doc = (await ctx.inspection()).docs;
    const documented = doc.companionDocumented;
    return verdict(r.ok && od?.status.startsWith("RESOLVED") && documented, ev(CLASS.STATIC, "uiuxTables.js + designTokens.js + uiContract.js + openDecisions.js", { ...r, od010: od?.status, documented }, { ok: true, tableCount: 11, od010: "RESOLVED_*", documented: true }, "Companion table completeness"));
  })

c("H03-008", "Repository auth policy: Apple and Google only", "No password routes/operations/fields or unapproved provider literals; recorded platform config is not live proof.", async (ctx) => {
    const surface=(await ctx.inspection()).authSurface;
    return verdict(surface.ok&&checkAuthPolicy().ok,ev(CLASS.STATIC,"repository auth manifest + recorded policy",{surface,recordedAt:OBSERVED_AUTH_METHODS.observedAt},{ok:true},"Repository policy only; Base44 Authentication panel and sign-in still require external verification"));
  })

c("H03-009", "Internal operations require server admin identity", "Anonymous, ordinary-user and forged-role requests denied before operation; admin permitted in synthetic runtime.", async () => {
    const result=await guardScenarios();
    return verdict(result.ok,ev(CLASS.SYNTHETIC_RUNTIME,"handleInternalRequest",result,{ok:true},"Injected server principals; not LIVE_ENFORCEMENT"));
  },{runnerType:RUNNER.RUNTIME,classification:CLASS.SYNTHETIC_RUNTIME})

c("H05-002", "Expected Pair-ID/content columns exist", "Pair ID, category and four TR/EN text columns are present.", withArtifacts((a) => {
    const missing = a.content260.columns.filter((x) => !x.present).map((x) => x.col);
    return check(missing.length === 0, { missing }, { missing: [] }, "Header check");
  }))

c("H05-003", "Six approved categories reconcile", "Category set and counts (30/66/56/32/44/32) match İş Analizi v2.5; mappings use only these six.", withArtifacts((a) => {
    const actual = { mismatches: a.content260.categoryCountMismatches, unknown: a.content260.unknownCategories,
      m192Categories: a.mapping192.categoriesUsed.length, m240Categories: a.mapping240.categoriesUsed.length,
      invalid: a.mapping192.invalidValues.length + a.mapping240.invalidValues.length,
      missingCategory: a.content260.missingCategory.length + a.mapping192.missingCategory.length + a.mapping240.missingCategory.length };
    return check(categoryIntegrity(a), actual, { mismatches: [], unknown: [], categories: 6, invalid: 0, missingCategory: 0 }, "Category reconciliation");
  }))

c("H05-007", "No duplicate IDs or mappings", "Pair IDs unique and well-formed; mapping combinations unique.", withArtifacts((a) => {
    const actual = { dupPairIds: a.content260.duplicateIds, badIds: a.content260.badIdFormat, missingIds:a.content260.missingIds, unexpectedIds:a.content260.unexpectedIds, dup192: a.mapping192.duplicates, dup240: a.mapping240.duplicates };
    return check(Object.values(actual).every((v) => Array.isArray(v)&&v.length === 0), actual, { all: [] }, "Exact SHF-001…260 set and duplicate detection");
  }))

c("H05-009", "Content import stage and exact verified readiness", "Approved 041/042/043/044/045/046/047/048/049/050/051 retain staged source/hash/count verification; pre-import differs from complete import and partial/conflicting rows fail.", async (ctx) => {
    let counts=null;
    const diagnostics = {};
    try { counts=await ctx.contentCounts(); } catch (error) { diagnostics.counts = healthReadDiagnostic(error); }
    let importPerformed = null;
    try { importPerformed = (await ctx.artifacts()).importPerformed; } catch (error) { diagnostics.artifacts = healthReadDiagnostic(error); }
    let verification=null;
    if(contentStatePolicy(BUILD_MARKER)==='VERIFIED_CONTENT_IMPORT_STAGES')try{verification=await ctx.contentLibrary();}catch(error){diagnostics.verification=healthReadDiagnostic(error);}
    const result=evaluateContentState(BUILD_MARKER,counts,importPerformed,verification);
    return verdict(result.status === 'PASS',ev(CLASS.LIVE_RUNTIME,'internalHealth contentCounts + validateContentArtifacts (live, read-only)',
      {buildMarker:BUILD_MARKER,counts,importPerformed,phase:verification?.phase,ready:verification?.ready,sourceHash:verification?.sourceHash,unexpected:result.unexpected||[],diagnostics},result.expected,result.code), result.status);
  })

makeCase('H09', { runnerType: RUNNER.BACKEND, classification: CLASS.LIVE_RUNTIME })('H09-004', 'Production first-Shinka prerequisites', 'Shared exact native contract: valid transient reads BLOCKED, malformed/mismatched rows FAIL; approved content and Moon readiness remain required. SS04/SS10 local matrix; hosted writes separate.', async ctx => {
    let library = null; try { library = await ctx.contentLibrary(); } catch { /* remains blocked */ }
    const prerequisite = await nativePrerequisite(ctx, 'daily');
    if (prerequisite.status !== 'PASS') return prerequisite;
    let moon; try { moon = await ctx.moonReadiness(); } catch { /* reported below */ }
    return verdict(library?.ready === true && moon?.ready === true, ev(CLASS.LIVE_RUNTIME, 'Base44 content + Moon verification', { contentReady: library?.ready, moonReady: moon?.ready }, 'verified approved content and current Moon coverage', 'Read-only prerequisites; H09-901 still requires hosted mutations.'), 'BLOCKED');
  })

import { localCase } from '../caseFactory';
import { SECURITY_TESTS } from '@/foundation/tests/securityTests';
import { CLASS, RUNNER, APPLICABILITY } from '../constants';
import { ev, blockedResult } from '../evidence';
import { makeCase } from '../caseFactory';
import { syntheticProbe } from './domainProbe';
const c=makeCase('H12',{classification:CLASS.SYNTHETIC_RUNTIME,runnerType:RUNNER.RUNTIME});
// First three stable IDs preserve the previous conceptual contract; others expand it.
const groups=[
 ['H12-001','User row isolation',['S01','S03','S04','S24']],
 ['H12-002','Admin cannot modify immutable records',['S12','S14']],
 ['H12-003','Internal tooling denied to non-admins',['S08']],
 ...SECURITY_TESTS.filter(([id])=>!['S01','S03','S04','S24','S12','S14','S08'].includes(id)).map(([id,title],i)=>[`H12-${String(i+4).padStart(3,'0')}`,title,[id]]),
];
export const H12_CASES=[
 ...groups.map(([id,title,ids])=>c(id,title,'Executes canonical backend/security helpers with isolated synthetic identities.',syntheticProbe(SECURITY_TESTS.filter(([testId])=>ids.includes(testId))))),
  localCase('H12','H12-025','Admin route and session regression','Local AN02–AN07, SS01–SS02 and SS06–SS13: real AuthProvider/routes/login with synthetic transport; 15s total session/settings deadline and fresh post-timeout retry with stale result isolation (SS13), bounded 700/1400ms transient retry with injected wait and actual logout/account timer cancellation, denied admin, lost session/role, coalescing, obsolete account responses and parallel settings/session order (membership refusal, logout, account change). Node AR01–AR08: exactly two auth phases for Home reopen/You read only; first daily, writes, account/consent and reset boundaries. checkStartupRoutes exercises the real App routes with both startup orders and old-account refusal/success. Node server classification separate; no live OAuth proof.'),
 c('H12-901','LIVE_ENFORCEMENT_REQUIRED','Separate deployed anonymous / owner A / owner B / admin evidence is mandatory.',async()=>blockedResult(ev(CLASS.LIVE_ENFORCEMENT,'Base44 deployed enforcement',{verified:false},'Independent identity denials, protected mutation rejection, timestamp/readback proof','No synthetic result can close live enforcement')),{classification:CLASS.LIVE_ENFORCEMENT,runnerType:RUNNER.NONE,applicability:APPLICABILITY.EXTERNAL,executionLocation:'EXTERNAL',blocker:false}),
];

