c("H13-001", "Design token source exists", "Token module defines color, typography, spacing, radii, control sizes, touch target, icons, motion and card.", async () => {
    const keys = ["color", "typography", "spacing", "radii", "control", "touchTargetMin", "iconFamily", "motion", "card"];
    const missing = keys.filter((k) => DESIGN_TOKENS[k] === undefined);
    return verdict(missing.length === 0 && DESIGN_TOKENS.theme === "account-preference" && DESIGN_TOKENS.defaultTheme === "light", ev(CLASS.STATIC, "src/foundation/designTokens.js", { missing, theme: DESIGN_TOKENS.theme, defaultTheme: DESIGN_TOKENS.defaultTheme, status: DESIGN_TOKENS.status }, { missing: [], theme: "account-preference", defaultTheme: "light" }, "Token inspection"));
  })

c("H13-002", "Minimum 44x44 touch target", "Token is 44 and every rendered Health control is at least 44x44.", async () => {
    if (!root()) return noRoot();
    const small = findSmallTargets(root(), DESIGN_TOKENS.touchTargetMin);
    return verdict(DESIGN_TOKENS.touchTargetMin === 44 && small.length === 0, ev(CLASS.LIVE_RUNTIME, "DOM getBoundingClientRect", { token: DESIGN_TOKENS.touchTargetMin, small }, { token: 44, small: [] }, "Rendered size check"));
  }, DOM)

c("H13-003", "Typography families rendered", "Headings render in Cormorant Garamond and body in Inter.", async () => {
    const r = root();
    if (!r) return noRoot();
    const h = r.querySelector("h1");
    const head = h ? getComputedStyle(h).fontFamily : "";
    const body = getComputedStyle(r).fontFamily;
    return verdict(/Cormorant Garamond/.test(head) && /Inter/.test(body), ev(CLASS.LIVE_RUNTIME, "getComputedStyle", { heading: head, body }, { heading: "Cormorant Garamond", body: "Inter" }, "Computed font check"));
  }, DOM)

c("H13-004", "Current Health viewport overflow", "Measures this rendered Health screen at its actual viewport; mobile/Build acceptance stays in local browser tests.", async () => {
    if (!root()) return noRoot();
    const width = document.documentElement.clientWidth, height = window.innerHeight;
    const scrollWidth = document.documentElement.scrollWidth;
    return verdict(width > 0 && scrollWidth <= width + 1, ev(CLASS.LIVE_RUNTIME,'current Health viewport', {width,height,scrollWidth,path:location.pathname}, {overflow:false}, 'Current viewport only; no inferred 320/360px or physical-device evidence'));
  }, DOM)

c("H13-005", "Accessible labels on interactive controls", "Every visible control (including icon-only) inside the Health page has an accessible name.", async () => {
    if (!root()) return noRoot();
    const unlabeled = findUnlabeledControls(root());
    return verdict(unlabeled.length === 0, ev(CLASS.LIVE_RUNTIME, "DOM accessible-name check", { unlabeled }, { unlabeled: [] }, "Accessible name scan"));
  }, DOM)

c("H13-006", "Canonical color tokens rendered exactly", "UI/UX v1.1 is READ, tokens APPROVED, and rendered Shinka CSS variables match the independently resolved light/manual-dark palette.", async () => {
    const src = SOURCE_INVENTORY.find((s) => s.id === "SRC-03");
    if (src.status !== "READ") return { status: STATUS.BLOCKED, evidence: ev(CLASS.BLOCKED_EXTERNAL, "SRC-03", src.status, "READ", "UI/UX v1.1 not received") };
    const { checkCssTokens } = await import("@/foundation/inspection/uiRules");
    const cs = getComputedStyle(document.documentElement);
    const expectedTheme = appThemeExpectation().theme;
    const r = checkCssTokens((v) => cs.getPropertyValue(v), expectedTheme);
    return verdict(DESIGN_TOKENS.status === "APPROVED_UIUX_V1_1" && r.mismatches.length === 0, ev(CLASS.LIVE_RUNTIME, "getComputedStyle(:root)", { status: DESIGN_TOKENS.status, expectedTheme, ...r }, { status: "APPROVED_UIUX_V1_1", mismatches: [] }, "Rendered token comparison"));
  }, DOM)

c("H13-007", "Typography contract (Medium headings, Inter labels)", "Token sizes match v1.1; a rendered heading uses weight 500; a rendered button label uses Inter 500.", async () => {
    const r = root();
    if (!r) return noRoot();
    const ty = DESIGN_TOKENS.typography;
    const sizesOk = JSON.stringify(ty.headingSizes) === HEADINGS && JSON.stringify(ty.bodySizes) === BODY;
    const m = headingAndLabel(r);
    return verdict(sizesOk && m.headingWeight === "500" && m.labelWeight === "500" && /Inter/.test(m.labelFamily), ev(CLASS.LIVE_RUNTIME, "tokens + getComputedStyle", { sizesOk, ...m }, { sizesOk: true, headingWeight: "500", labelWeight: "500", labelFamily: "Inter" }, "Typography check"));
  }, DOM)

c("H13-008", "Navigation and Lucide icon contract", "Bottom nav is exactly Home/Calendar/Pattern (house, calendar-days, moon); You is top-right user-round and not in bottom nav; icons resolve in lucide-react; Home, Calendar and Pattern use the shared contract-driven navigation.", async (ctx) => {
    const r = checkNavContract(iconExports());
    const shellUsesContract = (await ctx.inspection()).ui.shellUsesContract;
    return verdict(r.ok && shellUsesContract, ev(CLASS.STATIC, "uiContract.js + lucide-react + ProductNavigation + Home/Calendar/Pattern", { ...r, shellUsesContract }, { ok: true, shellUsesContract: true }, "Contract inspection"));
  })

c("H13-009", "Primary control geometry at least 52px", "Primary/input token minimum is 52 and every rendered primary control on the Health page is at least 52px tall.", async () => {
    const r = root();
    if (!r) return noRoot();
    const prim = primaryHeights(r);
    const k = DESIGN_TOKENS.control;
    const ok = k.primaryMinHeight === 52 && k.inputMinHeight === 52 && prim.length > 0 && prim.every((x) => x >= 52);
    return verdict(ok, ev(CLASS.LIVE_RUNTIME, "DOM getBoundingClientRect", { primaryHeights: prim, token: k }, { primaryHeights: "all >= 52", count: ">0" }, "Rendered height check"));
  }, DOM)

c("H13-010", "Rendered theme matches the verified application preference", "appTheme resolver's accepted account preference is independent of the measured DOM; unverified/onboarding defaults to light. OS changes never select the theme.", async () => {
    const expected = appThemeExpectation();
    const darkActive = document.documentElement.classList.contains('dark');
    const scheme = getComputedStyle(document.documentElement).colorScheme;
    const meta = document.querySelector('meta[name="color-scheme"]')?.getAttribute('content') ?? null;
    return verdict(darkActive === (expected.theme === 'dark') && scheme === expected.theme && (meta === null || meta === expected.theme), ev(CLASS.LIVE_RUNTIME, 'appTheme accepted input + independent DOM observation', { darkActive, scheme, meta }, expected, 'Verified view preference or unresolved light default; no OS/native permission claim'));
  }, { runnerType: RUNNER.DOM, classification: CLASS.LIVE_RUNTIME })

c("H13-011", "Centralized localization for Foundation UI", "EN/TR catalogs have identical non-empty keys; Foundation shell/state components hardcode no nav or retry strings.", async (ctx) => {
    const l = checkLocalization();
    const hard = (await ctx.inspection()).ui.hardcoded;
    return verdict(l.ok && !hard.length, ev(CLASS.STATIC, "i18n/strings.js + Foundation UI sources", { ...l, hardcoded: hard }, { ok: true, hardcoded: [] }, "Localization inspection"));
  })

c("H13-020", "046 section background mapping and single owner", "Five logical sections map to two native-size CDN assets (one shared watercolor for Home/Calendar/Pattern/You, one onboarding moon); unresolved state is neutral; at most one backdrop layer is rendered.", async () => {
    const urls = Object.keys(SECTION_BACKGROUNDS).map(s => sectionBackground(s).url);
    const layers = document.querySelectorAll(".shinka-section-backdrop").length;
    const actual = { sections: Object.keys(SECTION_BACKGROUNDS), distinctAssets: new Set(urls).size, neutral: sectionBackground("neutral"), layers };
    const ok = actual.sections.length === 5 && actual.distinctAssets === 2 && new Set(urls.slice(1)).size === 1 && actual.neutral === null && layers <= 1;
    return verdict(ok, ev(CLASS.STATIC, "sectionBackgrounds.js + rendered document", actual, { sections: 5, distinctAssets: 2, neutral: null, layers: "<=1" }, "Mapping and single-owner check; visual/WebView acceptance separate"));
  })

